// Wrapping old callback logic in a shiny new Promise
function getWeather() {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      const success = true;
      if (success) resolve("Sunny, 75°F");
      else reject("Weather API Down");
    }, 500);
  });
}

console.log("1. Requesting Weather...");

// No nesting! Flat, readable chains.
getWeather()
  .then((weather) => {
    console.log("2. Weather is:", weather);
    // We can return another promise here to chain it!
    return "Have a great day!"; 
  })
  .then((greeting) => {
    console.log("3. Greeting:", greeting);
  })
  .catch((error) => {
    // ONE catch block handles errors for the ENTIRE chain above it!
    console.error("Oh no:", error);
  });
